import stationData from "@/data/stations.json";
import priceData from "@/data/prices.json";

export type FuelInfo = { available: boolean; price: number | null };

// Fields marked optional/nullable may be missing from Redan's station list
// (src/data/stations.json is generated by scripts/import_stations.py).
export type Station = {
  id: string;
  name: string;
  aliases?: string[];
  city: string;
  address?: string | null;
  /** The site's cell number — always the contact to give customers. */
  phone?: string | null;
  /** Only set when the site has no cell number. */
  landline?: string | null;
  manager?: string | null;
  lat: number | null;
  lng: number | null;
  mapsLink?: string | null;
  hours: "24h" | "12h";
  openFrom?: string | null;
  openTo?: string | null;
  fuel: { blend: FuelInfo; diesel: FuelInfo };
  lubricants: boolean;
  refreshments?: boolean;
  lpg?: boolean;
};

export type RankedStation = Station & { distanceKm: number };

// Towns listed in prices.json get its (ZERA) pump prices; elsewhere the price
// comes from the station list, which currently has none.
const pricedTowns = new Set(priceData.towns.map((t) => t.toLowerCase()));

const stations = (stationData.stations as Station[]).map((s) => {
  if (!pricedTowns.has(s.city.trim().toLowerCase())) return s;
  const set = (f: FuelInfo, price: number): FuelInfo =>
    f.available ? { ...f, price } : f;
  return {
    ...s,
    fuel: {
      blend: set(s.fuel.blend, priceData.blendPerLitre),
      diesel: set(s.fuel.diesel, priceData.dieselPerLitre),
    },
  };
});

/** "9 October 2026" from "2026-10-09". */
const PRICE_DATE = new Date(`${priceData.effective}T00:00:00Z`).toLocaleDateString(
  "en-GB",
  { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" },
);
const PRICE_LABEL = `${priceData.source}, effective ${PRICE_DATE}`;

function inPricedTown(s: Station): boolean {
  return pricedTowns.has(s.city.trim().toLowerCase());
}

/** True when the seed file is still placeholder data rather than Redan's list. */
export const STATION_DATA_IS_PLACEHOLDER =
  stationData._meta?.status === "PLACEHOLDER";

export const PRICES_UPDATED_AT = priceData.effective;

/** False until map locations have been added for the stations. */
export const STATIONS_HAVE_LOCATIONS = stations.some(
  (s) => typeof s.lat === "number" && typeof s.lng === "number",
);

/** Great-circle distance in km. */
function haversineKm(
  aLat: number,
  aLng: number,
  bLat: number,
  bLng: number,
): number {
  const R = 6371;
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(bLat - aLat);
  const dLng = toRad(bLng - aLng);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(aLat)) * Math.cos(toRad(bLat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

export type StationQuery = {
  lat?: number;
  lng?: number;
  city?: string;
  fuelType?: "blend" | "diesel" | "any";
  onlyOpen24h?: boolean;
};

/**
 * Returns every matching station: ranked by distance from a coordinate, or
 * filtered by place name when no coordinate is given. Filters are applied
 * before ranking so "nearest 3 with diesel" returns three stations that
 * actually have diesel. The caller decides how many to show.
 */
/**
 * Stations matching a place or station name. Models often pass things like
 * "Redan Skyway, Harare" or "Skyway station", so filler words are dropped and,
 * failing a whole-phrase match, each comma/"in"-separated part is tried — a
 * station-name match first, so "Skyway, Harare" means Skyway, not all Harare.
 */
function matchPlace(pool: Station[], place: string): Station[] {
  const clean = (t: string) =>
    t
      .toLowerCase()
      .replace(/\b(redan|service|station|site|garage)\b/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  const matches = (needle: string, fields: (s: Station) => string[]) =>
    needle
      ? pool.filter((s) => fields(s).some((f) => f.toLowerCase().includes(needle)))
      : [];
  const byName = (s: Station) => [s.name, ...(s.aliases ?? [])];
  const byAny = (s: Station) => [s.city, s.address ?? "", ...byName(s)];

  const whole = clean(place);
  const direct = matches(whole, byAny);
  if (direct.length > 0) return direct;

  const parts = place.split(/,|\bin\b/i).map(clean).filter(Boolean);
  for (const part of parts) {
    const hit = matches(part, byName);
    if (hit.length > 0) return hit;
  }
  for (const part of parts) {
    const hit = matches(part, byAny);
    if (hit.length > 0) return hit;
  }

  // Single words, for phrases with extra place names ("Zindoga Waterfalls").
  // Station names before towns, so the station wins over a whole town.
  const words = whole.split(" ").filter((w) => w.length >= 4);
  for (const fields of [byName, byAny]) {
    const hit = pool.filter((s) =>
      fields(s).some((f) => words.some((w) => f.toLowerCase().includes(w))),
    );
    if (hit.length > 0) return hit;
  }

  // Last resort: tolerate a typo ("Zindonga") in a station or town name.
  const close = (w: string, target: string) =>
    Math.abs(w.length - target.length) <= 2 &&
    editDistance(w, target) <= (w.length >= 7 ? 2 : 1);
  for (const fields of [byName, byAny]) {
    const hit = pool.filter((s) =>
      fields(s).some((f) =>
        f.toLowerCase().split(/\s+/).some((t) => words.some((w) => close(w, t))),
      ),
    );
    if (hit.length > 0) return hit;
  }
  return [];
}

/** Levenshtein distance: how many single-letter edits turn a into b. */
function editDistance(a: string, b: string): number {
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(
        prev[j] + 1,
        cur[j - 1] + 1,
        prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1),
      );
    }
    prev = cur;
  }
  return prev[b.length];
}

/**
 * Station names mentioned anywhere in a free-text customer message, e.g.
 * "Ndoda kuziva nezve Redan Zindoga" -> ["Zindoga"]. Matches station names and
 * aliases only (not towns, which would pull in every Harare site), allowing a
 * one-letter typo in single-word names of five letters or more.
 */
export function stationsMentionedIn(text: string): string[] {
  const lower = ` ${text.toLowerCase().replace(/[^a-z0-9\s]/g, " ")} `;
  const words = lower.split(/\s+/).filter((w) => w.length >= 5);
  const found = new Set<string>();
  for (const s of stations) {
    for (const label of [s.name, ...(s.aliases ?? [])]) {
      const key = label.toLowerCase().replace(/^redan\s+/, "").trim();
      const exact = lower.includes(` ${key} `);
      const typo =
        !key.includes(" ") &&
        key.length >= 5 &&
        words.some((w) => Math.abs(w.length - key.length) <= 1 && editDistance(w, key) <= 1);
      if (exact || typo) found.add(s.name.replace(/^Redan\s+/, ""));
    }
  }
  return [...found];
}

export function findStations(q: StationQuery): RankedStation[] {
  const fuelType = q.fuelType ?? "any";

  let pool = stations;

  if (fuelType !== "any") {
    pool = pool.filter((s) => s.fuel[fuelType].available);
  }
  if (q.onlyOpen24h) {
    pool = pool.filter((s) => s.hours === "24h");
  }
  const hasCoords = typeof q.lat === "number" && typeof q.lng === "number";

  if (q.city) {
    const byCity = matchPlace(pool, q.city);

    if (byCity.length > 0) {
      pool = byCity;
    } else if (!hasCoords) {
      // Named a place we have no station in, and gave no coordinates to fall
      // back on. Return nothing rather than a list of unrelated stations —
      // handing the model arbitrary stations here is how a bot ends up quoting
      // a Harare price for a town it does not serve.
      return [];
    }
    // With coordinates we can still rank the full pool by real distance, so an
    // unrecognised place name is not fatal.
  }

  if (hasCoords && !q.city) {
    // Only stations with a known location can be ranked by distance.
    pool = pool.filter((s) => s.lat !== null && s.lng !== null);
  }

  const ranked: RankedStation[] = pool.map((s) => ({
    ...s,
    distanceKm:
      hasCoords && s.lat !== null && s.lng !== null
        ? Number(haversineKm(q.lat!, q.lng!, s.lat, s.lng).toFixed(1))
        : -1,
  }));

  if (hasCoords) {
    // Stations without a location (-1) go last.
    ranked.sort((a, b) =>
      a.distanceKm < 0 ? 1 : b.distanceKm < 0 ? -1 : a.distanceKm - b.distanceKm,
    );
  }

  return ranked;
}

/** From ZERA's price list, which names the petrol "Petrol Blend (E20)". */
export const BLEND_RATIO =
  "E20: 20% ethanol, 80% unleaded petrol (ZERA's current blending ratio)";

function fuelLine(f: FuelInfo, label = ""): string {
  if (!f.available) return "not available";
  return f.price !== null
    ? `${label}$${f.price.toFixed(2)}/L — ${PRICE_LABEL}`
    : `${label}available (pump price not listed — give ZERA's published price from the knowledge base with its date, and say to confirm at the station)`;
}

function lpgLine(s: Station): string {
  if (!s.lpg) return "no";
  return inPricedTown(s)
    ? `yes, $${priceData.lpgPerKg.toFixed(2)}/kg (${PRICE_LABEL})`
    : "yes";
}

function hoursLine(s: Station): string {
  if (s.hours === "24h") return "24 hours, every day";
  return s.openFrom && s.openTo
    ? `12 hours (${s.openFrom}–${s.openTo}), every day`
    : "NOT open 24 hours: a 12-hour station. Exact opening and closing times are not supplied, so tell the customer to call the station to confirm.";
}

/** A compact, model-friendly rendering of a station result. */
export function formatStation(s: RankedStation): Record<string, unknown> {
  const hasLocation = s.lat !== null && s.lng !== null;
  return {
    name: s.name,
    town: s.city,
    address: s.address ?? "not listed",
    phone: s.phone
      ? `${s.phone} (site cell number)`
      : s.landline
        ? `${s.landline} (landline — this site has no cell number)`
        : "not listed",
    site_manager: s.manager ?? "not listed",
    distance_km:
      s.distanceKm >= 0 ? s.distanceKm : "unknown (no location for this station or customer)",
    // Seed data's hours are made up, so only real station lists report them.
    ...(STATION_DATA_IS_PLACEHOLDER ? {} : { operating_hours: hoursLine(s) }),
    blend: fuelLine(s.fuel.blend, "Blend E20 (20% ethanol, 80% petrol): "),
    ...(s.fuel.blend.available && { blend_ratio: BLEND_RATIO }),
    diesel: fuelLine(s.fuel.diesel),
    lubricants: s.lubricants ? "yes" : "no",
    ...(s.refreshments !== undefined && { refreshments: s.refreshments ? "yes" : "no" }),
    ...(s.lpg !== undefined && { lpg_gas: lpgLine(s) }),
    maps_link: hasLocation
      ? `https://www.google.com/maps/search/?api=1&query=${s.lat},${s.lng}`
      : (s.mapsLink ??
        `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${s.name} ${s.city} Zimbabwe`)}`),
  };
}
